const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Define Atacama Desert region (approximate bounding box)
    var atacama = ee.Geometry.Rectangle([-71.0, -27.0, -68.0, -18.0]);

    // 2. Define time period: June and July 2025
    var startDate = '2025-06-01';
    var endDate = '2025-07-31';

    // 3. Try MODIS Terra snow cover product first (most appropriate for snow detection)
    var modisCol = ee.ImageCollection('MODIS/006/MOD10A1')
        .filterDate(startDate, endDate)
        .filterBounds(atacama);

    var colSize = modisCol.size().getInfo();
    console.log('MODIS Terra snow images:', colSize);

    if (colSize === 0) {
        // Try MODIS Aqua as fallback
        modisCol = ee.ImageCollection('MODIS/006/MYD10A1')
            .filterDate(startDate, endDate)
            .filterBounds(atacama);
        colSize = modisCol.size().getInfo();
        console.log('MODIS Aqua snow images:', colSize);
    }

    if (colSize === 0) {
        // No MODIS data, try Sentinel-2 with NDSI calculation
        console.log('No MODIS data, trying Sentinel-2...');
        var s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterDate(startDate, endDate)
            .filterBounds(atacama)
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

        var s2Size = s2Col.size().getInfo();
        console.log('Sentinel-2 images:', s2Size);

        if (s2Size === 0) {
            console.log('No images found in any collection.');
            console.log('<answer>C1</answer>');
            return;
        }

        // Process Sentinel-2: calculate NDSI for snow detection
        // NDSI = (Green - SWIR) / (Green + SWIR), snow when NDSI > 0.4
        var s2WithSnow = s2Col.map(function(img) {
            // Cloud masking using QA60 band
            var qa = img.select('QA60');
            var cloudMask = qa.bitwiseAnd(1 << 10).eq(0)  // Bit 10: clouds
                          .and(qa.bitwiseAnd(1 << 11).eq(0)); // Bit 11: cirrus

            var ndsi = img.normalizedDifference(['B3', 'B11']).rename('NDSI');
            var snowMask = ndsi.gt(0.4);  // Conservative snow threshold

            // Apply cloud mask and return snow mask
            return snowMask.updateMask(cloudMask);
        });

        // Create max composite (snow present at any time)
        var snowComposite = s2WithSnow.max();

        // Count snow pixels
        var snowStats = snowComposite.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: atacama,
            scale: 1000,
            maxPixels: 1e9,
            bestEffort: true
        });

        var snowCount = snowStats.get('NDSI').getInfo();
        var validPixels = snowComposite.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: atacama,
            scale: 1000,
            maxPixels: 1e9,
            bestEffort: true
        }).get('NDSI').getInfo();

        console.log('Sentinel-2 snow pixel count:', snowCount);
        console.log('Valid pixels in region:', validPixels);

        if (validPixels === 0) {
            console.log('No valid pixels after cloud masking.');
            console.log('<answer>C2</answer>');
            return;
        }

        if (snowCount === null || snowCount === undefined || isNaN(snowCount)) {
            console.log('Calculation failed.');
            console.log('<answer>C3</answer>');
            return;
        }

        if (snowCount > 0) {
            console.log('<answer>A</answer>');
        } else {
            console.log('<answer>B</answer>');
        }
        return;
    }

    // 4. Process MODIS data
    // Select NDSI_Snow_Cover band (0-100, higher values = more snow)
    var snowCol = modisCol.select('NDSI_Snow_Cover');

    // Create max composite (show maximum snow cover value for each pixel)
    var maxSnow = snowCol.max();

    // Count pixels with any snow (NDSI_Snow_Cover > 0)
    var snowMask = maxSnow.gt(0);  // Conservative: any snow detected

    // Get count of snow pixels
    var snowStats = snowMask.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: atacama,
        scale: 1000,
        maxPixels: 1e9,
        bestEffort: true
    });

    var snowCount = snowStats.get('NDSI_Snow_Cover').getInfo();

    // Get count of valid (unmasked) pixels
    var validStats = maxSnow.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: atacama,
        scale: 1000,
        maxPixels: 1e9,
        bestEffort: true
    });

    var validPixels = validStats.get('NDSI_Snow_Cover').getInfo();

    console.log('MODIS snow pixel count:', snowCount);
    console.log('Valid pixels in region:', validPixels);

    // 5. Validation and answer
    if (validPixels === 0) {
        console.log('No valid pixels in MODIS data.');
        console.log('<answer>C2</answer>');
        return;
    }

    if (snowCount === null || snowCount === undefined || isNaN(snowCount)) {
        console.log('Calculation failed.');
        console.log('<answer>C3</answer>');
        return;
    }

    if (snowCount > 0) {
        console.log('<answer>A</answer>');
    } else {
        console.log('<answer>B</answer>');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
